-- =============================================================================
-- 011_rubric_seed.sql
-- The Hub — Phase 3, migration 11: the live rubric, migrated.
--
-- 77 behaviors, 314 answer options,
-- 12 sections. Generated from the live reviewer_form_points export, not
-- retyped, so nothing drifts in transcription.
--
-- Objective questions come from the Reviewer Form. Impression questions come
-- from Call Tracking Metrics, where the shopper enters them. That division
-- already exists in the live data and is preserved exactly.
--
-- possible_points is the maximum across a question's answer options, which is
-- how the current engine already computes it. Conditional questions therefore
-- keep producing a per-call denominator rather than a fixed total.
--
-- Requires: 001 to 010
-- =============================================================================

BEGIN;

VALUES ('Dead Ringers CX', 'cx', '2026.09',
        'Migrated from the live BigQuery scoring engine, September 2026')
ON CONFLICT (name, version) DO NOTHING;

-- Objective:   66 questions,    111 points
-- Impression:  11 questions,     29 points
-- Total:       77 questions,    140 points

-- -----------------------------------------------------------------------------
-- behaviors
-- -----------------------------------------------------------------------------
ON CONFLICT (code) DO NOTHING;

-- -----------------------------------------------------------------------------
-- behavior_answers — points live on the option, which is what makes the
-- FTC verdict a formula rather than a judgment
-- -----------------------------------------------------------------------------
ON CONFLICT (behavior_id, answer_value) DO NOTHING;

COMMIT;

